DROP INDEX "pending_action_expiry_scoped_idx";--> statement-breakpoint
DROP INDEX "pending_action_expiry_unscoped_probe_idx";--> statement-breakpoint
CREATE INDEX "pending_action_expiry_scoped_idx" ON "pending_action" USING btree ("expires_at","id") WHERE state = 'pending' AND (workspace_id IS NOT NULL OR (workspace_id IS NULL AND (project_id IS NULL AND ( (organisation_id IS NULL AND ( (action = 'delete' AND target_type = 'user' AND route_key = 'POST /api/instance/users/{id}/deactivate') OR (action = 'user_deactivation' AND target_type = 'person' AND route_key = 'POST /api/instance/users/{id}/deactivate') OR (action = 'delete' AND target_type = 'identity_connection' AND route_key = 'DELETE /api/instance/identity-connections/{id}' AND cardinality(target_ids) = 1) )) OR (organisation_id IS NOT NULL AND organisation_id = target_ids[1] AND cardinality(target_ids) = 1 AND target_type = 'organisation' AND ( (action = 'delete' AND route_key = 'DELETE /api/instance/organisations/{id}') OR (action = 'purge' AND route_key = 'POST /api/instance/purge') )) ))));--> statement-breakpoint
CREATE INDEX "pending_action_expiry_unscoped_probe_idx" ON "pending_action" USING btree ("expires_at") WHERE state = 'pending' AND workspace_id IS NULL AND NOT (project_id IS NULL AND ( (organisation_id IS NULL AND ( (action = 'delete' AND target_type = 'user' AND route_key = 'POST /api/instance/users/{id}/deactivate') OR (action = 'user_deactivation' AND target_type = 'person' AND route_key = 'POST /api/instance/users/{id}/deactivate') OR (action = 'delete' AND target_type = 'identity_connection' AND route_key = 'DELETE /api/instance/identity-connections/{id}' AND cardinality(target_ids) = 1) )) OR (organisation_id IS NOT NULL AND organisation_id = target_ids[1] AND cardinality(target_ids) = 1 AND target_type = 'organisation' AND ( (action = 'delete' AND route_key = 'DELETE /api/instance/organisations/{id}') OR (action = 'purge' AND route_key = 'POST /api/instance/purge') )) ));